// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount, uint256 bal) public {
        // Admissible domain: amount is large enough to exceed the funded balance
        amount = bound(amount, 2, type(uint256).max);
        bal = bound(bal, 1, amount - 1);

        // The test contract is c's owner (deployed in setUp), so calls come from the owner.
        // Fund the contract with strictly less than the requested amount.
        vm.deal(address(c), bal);

        address receiver = address(0xdEaD); // plain EOA receiver (not the deciding value)

        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: sendTo must revert whenever the contract's balance cannot cover
        // the full requested amount. The reference transfers `amount` (> bal) and reverts;
        // the mutant transfers 1 wei (<= bal) and succeeds, breaking the rule.
        assertTrue(!ok, "sendTo must revert when balance < amount");
    }
}
